#: The p4-verify supplement (wip/p4-verify-sup): the reviews' findings C1-C7 and R1-R5, D2,
#: D3 as section 7 stands on 2026-09-23 (with the shared-comma refusal), the V8 domain form,
#: the card-held re-verification and the reverted lane rows of the acceptance. One guard, one
#: test that must fail when it is broken.
